80	// listPlacements handles GET /v1/placements, both the single-record form
81	// (namespace+name) and the filtered-list form.
82	func (h *placementHandler) listPlacements(c *gin.Context) {
83		params, err := parseQuery(c.Request.URL.RawQuery)
84		if err != nil {
85			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
86			return
87		}
88	
89		if name, hasName := params["name"]; hasName {
90			namespace, hasNamespace := params["namespace"]
91			_, hasQueue := params["queue"]
92			_, hasNode := params["node"]
93			if !hasNamespace || hasQueue || hasNode {
94				writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
95				return
96			}
97			rec, err := h.st.Get(c.Request.Context(), namespace, name)
98			if errors.Is(err, store.ErrNotFound) {
99				writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
100				return
101			}
102			if err != nil {
103				writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
104				return
105			}
