107			return
108		}
109	
110		recs, err := h.st.List(c.Request.Context(), store.ListFilter{
111			Namespace: params["namespace"],
112			Queue:     params["queue"],
113			Node:      params["node"],
114		})
115		if err != nil {
116			writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
117			return
118		}
119		if recs == nil {
120			recs = []*store.Placement{}
121		}
122		c.JSON(http.StatusOK, gin.H{"items": recs})
