124	
125	var allowedQueryParams = map[string]bool{
126		"namespace": true,
127		"name":      true,
128		"queue":     true,
129		"node":      true,
130	}
131	
132	// parseQuery accepts only the four documented parameters. Empty values,
133	// repeated parameters and malformed query strings are rejected.
134	func parseQuery(raw string) (map[string]string, error) {
135		values, err := url.ParseQuery(raw)
136		if err != nil {
137			return nil, errInvalidPlacement
138		}
139		params := make(map[string]string, len(values))
140		for key, vals := range values {
141			if !allowedQueryParams[key] || len(vals) != 1 || vals[0] == "" {
142				return nil, errInvalidPlacement
143			}
144			params[key] = vals[0]
145		}
146		return params, nil
147	}
148	
149	// decide performs the trial placement: among nodes whose labels contain every
150	// selector pair and whose capacity fits the request, it picks the name that is
151	// smallest in UTF-8 byte order. Capacity is only probed and never deducted.
152	func decide(p *store.Placement) (status string, node *string, reason *string) {
153		var chosen string
154		for i := range p.Nodes {
155			n := &p.Nodes[i]
156			if !labelsSatisfy(n.Labels, p.Selector) {
157				continue
158			}
159			if n.CPU < p.Resources.CPU || n.Memory < p.Resources.Memory {
160				continue
161			}
162			if chosen == "" || n.Name < chosen {
163				chosen = n.Name
164			}
165		}
166		if chosen != "" {
167			n := chosen
168			return statusPlaced, &n, nil
169		}
170		r := reasonNoNode
171		return statusRejected, nil, &r
172	}
173	
174	func labelsSatisfy(labels, selector map[string]string) bool {
175		for key, want := range selector {
176			got, ok := labels[key]
177			if !ok || got != want {
178				return false
179			}
180		}
181		return true
182	}
183	
184	// ---------------------------------------------------------------------------
185	// Strict request parsing.
186	//
187	// The token walk below enforces, before anything is stored:
188	//   - the body is one JSON object with exactly the documented members,
189	//   - no unknown or duplicate member names at any level,
190	//   - no trailing data after the root object,
191	//   - every value has the declared JSON type and range (null is never accepted
192	//     where a value is required; omitted selector/labels default to {}),
193	//   - node names are unique.
194	// ---------------------------------------------------------------------------
195	
196	var topLevelFields = map[string]bool{
197		"namespace": true,
198		"name":      true,
199		"queue":     true,
200		"priority":  true,
201		"resources": true,
202		"selector":  true,
203		"nodes":     true,
204	}
205	
206	var resourceFields = map[string]bool{"cpu": true, "memory": true}
207	
208	var nodeFields = map[string]bool{
209		"name":   true,
210		"cpu":    true,
211		"memory": true,
212		"labels": true,
213	}
214	
215	func parsePlacement(body []byte) (*store.Placement, error) {
216		dec := json.NewDecoder(bytes.NewReader(body))
217		dec.UseNumber()
218	
219		tok, err := dec.Token()
220		if err != nil {
221			return nil, errInvalidPlacement
222		}
223		if d, ok := tok.(json.Delim); !ok || d != '{' {
224			return nil, errInvalidPlacement
225		}
226	
227		p := &store.Placement{}
228		seen := map[string]bool{}
229		for dec.More() {
230			keyTok, err := dec.Token()
231			if err != nil {
232				return nil, errInvalidPlacement
233			}
234			key, ok := keyTok.(string)
235			if !ok || !topLevelFields[key] || seen[key] {
236				return nil, errInvalidPlacement
237			}
238			seen[key] = true
239	
240			var raw json.RawMessage
241			if err := dec.Decode(&raw); err != nil {
242				return nil, errInvalidPlacement
243			}
244	
245			switch key {
246			case "namespace", "name", "queue":
247				s, err := parseTrimmedString(raw)
248				if err != nil {
249					return nil, err
250				}
251				switch key {
252				case "namespace":
253					p.Namespace = s
254				case "name":
255					p.Name = s
256				case "queue":
257					p.Queue = s
258				}
259			case "priority":
260				n, err := parseBoundedInt(raw, 32)
261				if err != nil {
262					return nil, err
263				}
264				p.Priority = int32(n)
265			case "resources":
266				r, err := parseResources(raw)
267				if err != nil {
268					return nil, err
269				}
270				p.Resources = r
271			case "selector":
272				m, err := parseStringMap(raw)
273				if err != nil {
274					return nil, err
275				}
276				p.Selector = m
277			case "nodes":
278				nodes, err := parseNodes(raw)
279				if err != nil {
280					return nil, err
281				}
282				p.Nodes = nodes
283			}
284		}
285		if _, err := dec.Token(); err != nil {
286			return nil, errInvalidPlacement // closing '}'
287		}
288		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
289			return nil, errInvalidPlacement // trailing data
290		}
291	
292		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
293			if !seen[required] {
294				return nil, errInvalidPlacement
295			}
296		}
297		if p.Selector == nil {
298			p.Selector = map[string]string{}
299		}
300		return p, nil
301	}
302	
303	func parseResources(raw json.RawMessage) (store.Resources, error) {
304		var r store.Resources
305		obj, err := parseStrictObject(raw, resourceFields)
306		if err != nil {
307			return r, err
308		}
309		cpuRaw, ok := obj["cpu"]
310		if !ok {
311			return r, errInvalidPlacement
312		}
313		memoryRaw, ok := obj["memory"]
314		if !ok {
315			return r, errInvalidPlacement
316		}
317		cpu, err := parseBoundedInt(cpuRaw, 64)
318		if err != nil || cpu <= 0 {
319			return r, errInvalidPlacement
320		}
321		memory, err := parseBoundedInt(memoryRaw, 64)
322		if err != nil || memory <= 0 {
323			return r, errInvalidPlacement
324		}
325		return store.Resources{CPU: cpu, Memory: memory}, nil
326	}
327	
328	func parseNodes(raw json.RawMessage) ([]store.Node, error) {
329		if isNull(raw) {
330			return nil, errInvalidPlacement
331		}
332		dec := json.NewDecoder(bytes.NewReader(raw))
333		tok, err := dec.Token()
334		if err != nil {
335			return nil, errInvalidPlacement
336		}
337		if d, ok := tok.(json.Delim); !ok || d != '[' {
338			return nil, errInvalidPlacement
339		}
340	
341		nodes := []store.Node{}
342		names := map[string]bool{}
343		for dec.More() {
344			var elem json.RawMessage
345			if err := dec.Decode(&elem); err != nil {
346				return nil, errInvalidPlacement
347			}
348			obj, err := parseStrictObject(elem, nodeFields)
349			if err != nil {
350				return nil, err
351			}
352			nameRaw, ok := obj["name"]
353			if !ok {
354				return nil, errInvalidPlacement
355			}
356			cpuRaw, ok := obj["cpu"]
357			if !ok {
358				return nil, errInvalidPlacement
359			}
360			memoryRaw, ok := obj["memory"]
361			if !ok {
362				return nil, errInvalidPlacement
363			}
364			name, err := parseTrimmedString(nameRaw)
365			if err != nil {
366				return nil, err
367			}
368			cpu, err := parseBoundedInt(cpuRaw, 64)
369			if err != nil || cpu < 0 {
370				return nil, errInvalidPlacement
371			}
372			memory, err := parseBoundedInt(memoryRaw, 64)
373			if err != nil || memory < 0 {
374				return nil, errInvalidPlacement
375			}
376			labels := map[string]string{}
377			if labelRaw, ok := obj["labels"]; ok {
378				labels, err = parseStringMap(labelRaw)
379				if err != nil {
380					return nil, err
381				}
382			}
383			if names[name] {
384				return nil, errInvalidPlacement
385			}
386			names[name] = true
387			nodes = append(nodes, store.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
388		}
389		if _, err := dec.Token(); err != nil {
390			return nil, errInvalidPlacement // closing ']'
391		}
392		return nodes, nil
393	}
394	
395	// parseStrictObject decodes an object whose member names are restricted to
396	// allowed. Both unknown and duplicate names are rejected.
397	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
398		if isNull(raw) {
399			return nil, errInvalidPlacement
400		}
401		dec := json.NewDecoder(bytes.NewReader(raw))
402		tok, err := dec.Token()
403		if err != nil {
404			return nil, errInvalidPlacement
405		}
406		if d, ok := tok.(json.Delim); !ok || d != '{' {
407			return nil, errInvalidPlacement
408		}
409		return readObjectMembers(dec, allowed)
410	}
411	
412	// parseStringMap decodes an object with arbitrary string keys and string
413	// values; null or non-string values are rejected.
414	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
415		if isNull(raw) {
416			return nil, errInvalidPlacement
417		}
418		dec := json.NewDecoder(bytes.NewReader(raw))
419		tok, err := dec.Token()
420		if err != nil {
421			return nil, errInvalidPlacement
422		}
423		if d, ok := tok.(json.Delim); !ok || d != '{' {
424			return nil, errInvalidPlacement
425		}
426	
427		out := map[string]string{}
428		raws, err := readObjectMembers(dec, nil)
429		if err != nil {
430			return nil, err
431		}
432		for key, value := range raws {
433			s, err := parseJSONString(value)
434			if err != nil {
435				return nil, err
436			}
437			out[key] = s
438		}
439		return out, nil
440	}
441	
442	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
443		out := map[string]json.RawMessage{}
444		for dec.More() {
445			keyTok, err := dec.Token()
446			if err != nil {
447				return nil, errInvalidPlacement
448			}
449			key, ok := keyTok.(string)
450			if !ok {
451				return nil, errInvalidPlacement
452			}
453			if allowed != nil && !allowed[key] {
454				return nil, errInvalidPlacement
455			}
456			if _, dup := out[key]; dup {
457				return nil, errInvalidPlacement
458			}
459			var value json.RawMessage
460			if err := dec.Decode(&value); err != nil {
461				return nil, errInvalidPlacement
462			}
463			out[key] = value
464		}
465		if _, err := dec.Token(); err != nil {
466			return nil, errInvalidPlacement // closing '}'
467		}
468		return out, nil
469	}
470	
471	// parseTrimmedString accepts a JSON string that is non-empty and has no
472	// leading or trailing Unicode whitespace.
473	func parseTrimmedString(raw json.RawMessage) (string, error) {
474		s, err := parseJSONString(raw)
475		if err != nil {
476			return "", err
477		}
478		if s == "" || s != strings.TrimSpace(s) {
479			return "", errInvalidPlacement
480		}
481		return s, nil
482	}
483	
484	func parseJSONString(raw json.RawMessage) (string, error) {
485		if isNull(raw) {
486			return "", errInvalidPlacement
487		}
488		var s string
489		if err := json.Unmarshal(raw, &s); err != nil {
490			return "", errInvalidPlacement
491		}
492		return s, nil
493	}
494	
495	// parseBoundedInt accepts an integral JSON number without fraction or exponent
496	// that fits a signed integer of the given bit size (32 or 64).
497	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
498		if isNull(raw) {
499			return 0, errInvalidPlacement
500		}
501		dec := json.NewDecoder(bytes.NewReader(raw))
502		dec.UseNumber()
503		var value any
504		if err := dec.Decode(&value); err != nil {
505			return 0, errInvalidPlacement
506		}
507		number, ok := value.(json.Number)
508		if !ok {
509			return 0, errInvalidPlacement
510		}
511		n, err := strconv.ParseInt(number.String(), 10, bitSize)
512		if err != nil {
513			return 0, errInvalidPlacement
514		}
515		return n, nil
516	}
517	
518	func isNull(raw json.RawMessage) bool {
519		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
520	}
521

